const std = @import("std"); const builtin = @import("builtin"); const http = @import("http"); const spaw = @import("spawn"); const regi = @import("registry"); const stre = @import("stream"); const cwdi = @import("cwd"); const stor = @import("store"); const hist = @import("history"); const watc = @import("watch"); const taskStor = @import("taskstore"); const taskTime = @import("tasktime"); const tick = @import("ticker"); const stat = @import("static"); const builOpti = @import("build_options");
pub const CF = .{ .body_maxz = 8 * 1024 * 1024, .requ_buff = 16 * 1024, .writ_buff = 64 * 1024, .line_buff = 8192, .task_maxz = 500, .logz_tail_maxz = 64 * 1024, .conn_maxz = 128, .conn_stak = 1024 * 1024, .reap_stak = 1024 * 1024, .reap_msec = 1000, .back_msec = 50, .atta_msec = 100, .head_dead_msec = 10_000, .hear_msec = 5_000, .stdi_maxz = 64 * 1024 };
pub const GUAR_LIST = [_][]const u8{ "cmrn_hist", "cmrn_favs" };
pub const Slot = struct { strm: ?*std.Io.net.Stream = null, sinc: i64 = 0, arme: bool = false };
pub const Ctxz = struct { gpaz: std.mem.Allocator, iozz: std.Io, uizz_root: []const u8, regz: regi.Regi = .{}, sess: cwdi.Sess = .{}, watc: watc.Watc = .{}, relo_msec: i64 = 0, uizz_seen_msec: i64 = 0, relo_mute: std.Io.Mutex = .init, sche: *tick.Sche, cach: stat.Cach, shel_json: []const u8 = "[]", slot: [CF.conn_maxz]Slot = @splat(.{}), slot_mute: std.Io.Mutex = .init };
pub fn guarChec(keyz: []const u8) bool { for (GUAR_LIST) |guar| if (std.mem.eql(u8, guar, keyz)) return true; return false; }
pub fn listEmpt(valu: std.json.Value) bool { return switch (valu) { .null => true, .string => |strz| blok: { const trim = std.mem.trim(u8, strz, " \t\r\n"); if (trim.len == 0) break :blok true; if (trim[0] != '[') break :blok false; const inne = std.mem.trim(u8, trim[1..], " \t\r\n"); break :blok inne.len > 0 and inne[0] == ']'; }, .array => |arra| arra.items.len == 0, else => false }; }
pub fn shelJson(gpaz: std.mem.Allocator, iozz: std.Io) []const u8 { var aren = std.heap.ArenaAllocator.init(gpaz); defer aren.deinit(); const list = spaw.shelAvai(aren.allocator(), iozz); var outz: std.Io.Writer.Allocating = .init(gpaz); std.json.Stringify.value(list, .{}, &outz.writer) catch return "[]"; return outz.toOwnedSlice() catch "[]"; }
pub fn plusWrit(wrtr: *std.Io.Writer, plus: std.json.Value, pref: []const u8) !void { try wrtr.writeAll(pref); try std.json.Stringify.value(plus, .{}, wrtr); }
pub fn optiStrzWrit(wrtr: *std.Io.Writer, keyz: []const u8, valu: ?[]const u8) !void { try wrtr.print(",\"{s}\":", .{keyz}); if (valu) |strz| try std.json.Stringify.encodeJsonString(strz, .{}, wrtr) else try wrtr.writeAll("null"); }
pub fn strzLess(_: void, left: []const u8, righ: []const u8) bool { return std.mem.lessThan(u8, left, righ); }
pub fn jsonStrz(valu: std.json.Value, keyz: []const u8) ?[]const u8 { if (valu != .object) return null; const fiel = valu.object.get(keyz) orelse return null; return if (fiel == .string) fiel.string else null; }
pub fn jsonIden(allo: std.mem.Allocator, valu: std.json.Value, keyz: []const u8) ?[]const u8 { if (valu != .object) return null; const fiel = valu.object.get(keyz) orelse return null; return switch (fiel) { .string => |strz| strz, .integer => |intz| std.fmt.allocPrint(allo, "{d}", .{intz}) catch null, else => null }; }
pub fn jsonBool(valu: std.json.Value, keyz: []const u8) ?bool { if (valu != .object) return null; const fiel = valu.object.get(keyz) orelse return null; return if (fiel == .bool) fiel.bool else null; }
pub fn jsonInte(valu: std.json.Value, keyz: []const u8) ?i64 { if (valu != .object) return null; const fiel = valu.object.get(keyz) orelse return null; return switch (fiel) { .integer => |inte| inte, .float => |floa| if (std.math.isFinite(floa) and @abs(floa) < 9e18) @as(i64, @intFromFloat(floa)) else null, else => null }; }
pub fn bannPrin(port: u16, uizz_root: []const u8) void { std.debug.print("\n  auto-task  ─ local command runner\n  ──────────────────────────────\n  listening →  http://127.0.0.1:{d}\n  ui root   →  {s}\n  platform  →  {s}\n\n  open the URL above in your browser.\n\n", .{ port, uizz_root, @tagName(builtin.os.tag) }); }
pub fn listWoulEmpt(allo: std.mem.Allocator, iozz: std.Io, inco: std.json.Value) bool { if (inco != .object) return false; const stor_rawz = stor.load(allo, iozz, "config.json"); const stor_valu = std.json.parseFromSliceLeaky(std.json.Value, allo, stor_rawz, .{}) catch return false; if (stor_valu != .object) return false; for (GUAR_LIST) |keyz| { if (listEmpt(stor_valu.object.get(keyz) orelse .null)) continue; if (listEmpt(inco.object.get(keyz) orelse .null)) return true; } return false; }
pub fn outpWoulEmpt(allo: std.mem.Allocator, iozz: std.Io, inco: std.json.Value) bool { if (inco != .object) return false; const stor_rawz = stor.load(allo, iozz, "output.json"); const stor_valu = std.json.parseFromSliceLeaky(std.json.Value, allo, stor_rawz, .{}) catch return false; if (stor_valu != .object) return false; var iter = stor_valu.object.iterator(); while (iter.next()) |pair| { const hadz = pair.value_ptr.*; if (hadz != .array or hadz.array.items.len == 0) continue; const nowz = inco.object.get(pair.key_ptr.*) orelse return true; if (nowz != .array or nowz.array.items.len == 0) return true; } return false; }
